  static string ExtractArt(string source){var lines=source.Replace("\r","").Split('\n');int end=Array.FindIndex(lines,l=>l.Contains("【이름】"));return string.Join("\n",lines.Take(end>0?end-1:lines.Length).Select(l=>System.Text.RegularExpressions.Regex.Replace(l,@"\s+[♂♀？]\s*[OXＯＸ]\s*$",""))).Trim('\n');}
   void Arrange(){int clientWidth=Math.Max(1,ClientSize.Width),clientHeight=Math.Max(1,ClientSize.Height);int inspector=Math.Max(260,Math.Min(380,clientWidth/4));int arena=Math.Max(1,clientWidth-inspector-12);int margin=Math.Min(34,Math.Max(8,arena/12));int gap=Math.Min(170,Math.Max(32,arena-margin*2-2));int availableWidth=Math.Max(2,arena-margin*2-gap),width=Math.Max(1,availableWidth/2),top=121,commandHeight=36,bottom=Math.Max(top+180,clientHeight-62);int verticalSpace=Math.Max(1,bottom-top);int moveHeight=Math.Min(154,Math.Max(110,verticalSpace/3));int artHeight=Math.Max(1,verticalSpace-moveHeight-commandHeight-27);brand.SetBounds(margin,16,200,40);guide.SetBounds(margin+200,20,110,36);teamEditor.SetBounds(margin+318,20,100,36);fieldLabel.SetBounds(margin,66,Math.Max(1,arena-margin*2),30);turnLabel.SetBounds(Math.Max(0,arena/2-100),16,200,40);settings.SetBounds(Math.Max(0,arena-margin-306),20,100,36);results.SetBounds(Math.Max(0,arena-margin-198),20,100,36);reset.SetBounds(Math.Max(0,arena-margin-90),20,90,36);for(int i=0;i<2;i++){int x=i==0?margin:Math.Max(margin,arena-margin-width);cards[i].SetBounds(x,top,width,artHeight);int actionY=Math.Max(top+artHeight+4,bottom-moveHeight-commandHeight-7);directiveButtons[i].SetBounds(x,actionY,Math.Max(1,width-228),commandHeight);extensionButtons[i].SetBounds(Math.Max(x,x+width-220),actionY,108,commandHeight);analyzeButtons[i].SetBounds(Math.Max(x,x+width-108),actionY,108,commandHeight);moveCards[i].SetBounds(x,Math.Max(actionY+commandHeight+4,bottom-moveHeight),width,moveHeight);}int badgeWidth=Math.Max(92,gap-12),badgeHeight=Math.Min(105,Math.Max(72,artHeight/4));fieldEffectBadge.SetBounds(Math.Max(0,arena/2-badgeWidth/2),top+Math.Max(62,(artHeight-badgeHeight)/2),badgeWidth,badgeHeight);calculate.SetBounds(Math.Max(0,arena/2-66),Math.Max(top+artHeight+8,bottom-moveHeight+30),132,72);back.SetBounds(Math.Max(0,arena/2-51),Math.Max(0,bottom-42),102,28);status.SetBounds(margin,Math.Min(clientHeight-52,Math.Max(0,bottom+8)),Math.Max(1,arena-margin*2),48);battleState.SetBounds(Math.Min(clientWidth-1,arena+5),18,Math.Max(1,clientWidth-arena-17),Math.Max(1,clientHeight-36));fieldEffectBadge.BringToFront();}
  void Save(){undo.Push(new Snapshot{Fighters=Fighters.Select(f=>f.Copy()).ToArray(),Reserves=reserves.Select(x=>x.Select(f=>f.Copy()).ToList()).ToArray(),Trainers=trainerStates.Select(x=>x.Copy()).ToArray(),Selections=selections.Select(x=>x.Copy()).ToArray(),Rules=Rules.Copy(),Turn=turn,Log=log});}
  void Undo(){if(undo.Count==0)return;var s=undo.Pop();Fighters=s.Fighters;reserves=s.Reserves;trainerStates=s.Trainers;selections=s.Selections;Rules=s.Rules;turn=s.Turn;log=s.Log;RefreshView();}
  void ResetFighter(Fighter f,bool heal){f.Stages=new int[6];f.AccuracyStage=f.EvasionStage=f.CriticalStage=0;f.TrainerAccuracyStage=f.TrainerCriticalStage=0;f.AccuracyMultiplier=f.EvasionMultiplier=1;f.Multipliers=new[]{1d,1d,1d,1d,1d,1d};f.Status="정상";f.Conditions=new ConditionState();if(heal)f.HP=Engine.Stats(f,f.Data.level,new Rules())[0];}
  void Bench(Fighter f){Mechanics.LeaveField(f);}
  void SelectDirective(int side){if(Fighters[side].HP>0&&Mechanics.AutoAction(Fighters[side]))return;if(Fighters[side].HP<=0){ReplaceFainted();return;}using(var dialog=new DirectiveForm(trainers[side],trainerStates[side],reserves[side],Fighters[side],selections[side]))if(dialog.ShowDialog(this)==DialogResult.OK){selections[side]=dialog.Value;RefreshView();}}
  void Edit(int side){using(var dialog=new FighterForm(db,Fighters[side],Fighters[1-side].Data.level,Rules)){if(dialog.ShowDialog(this)==DialogResult.OK){Save();Fighters[side]=dialog.Value;RefreshView();}}}
  void EditConditions(int side){using(var dialog=new ConditionsForm(db,Fighters[side],Fighters[1-side],Rules)){if(dialog.ShowDialog(this)==DialogResult.OK){Save();Fighters[side]=dialog.Value;RefreshView();}}}
   void Battle(){if(Fighters.Any(f=>f.HP<=0))return;var commands=new BattleCommand[2];var rangeLines=new List<string>();for(int i=0;i<2;i++){var pick=selections[i];var party=reserves[i].Concat(new[]{Fighters[i]}).ToArray();if(Mechanics.AutoAction(Fighters[i])){commands[i]=new BattleCommand{Move=Mechanics.ActionMove(db,Fighters[i],null),Party=party};rangeLines.Add(Fighters[i].Data.name+" · "+Mechanics.AutoActionLabel(Fighters[i])+" 자동 행동");continue;}if(pick.SwitchIndex>=0){if(pick.SwitchIndex>=reserves[i].Count){GameDialog.Show(this,"교대 대상을 다시 선택하세요.");return;}commands[i]=new BattleCommand{SwitchIn=reserves[i][pick.SwitchIndex],Form=pick.Form,Order=pick.Order,PreInputs=(pick.PreInputs??new List<string>()).ToArray(),Party=party};rangeLines.Add(Fighters[i].Data.name+" · 교대 → "+commands[i].SwitchIn.Data.name);}else{bool extension=(pick.ExtensionMove??"").Length>0&&db.moves.Any(x=>x.name==pick.ExtensionMove);var m=extension?db.moves.First(x=>x.name==pick.ExtensionMove):db.moves.First(x=>x.name==Fighters[i].Moves[Math.Min(Fighters[i].Selected,Fighters[i].Moves.Length-1)]);if(extension)rangeLines.Add(Fighters[i].Data.name+" · 기능확장");commands[i]=new BattleCommand{Move=m,Extension=extension,Form=pick.Form,Order=pick.Order,PreInputs=(pick.PreInputs??new List<string>()).ToArray(),Party=party};var d=Engine.Calculate(db,Fighters[i],Fighters[1-i],m,Rules,i);rangeLines.Add(Fighters[i].Data.name+" · "+m.name+"   "+(d.Supported?d.Min+" – "+d.Max+"  (자속 ×"+d.Stab+", 상성 ×"+d.Type+")":(Mechanics.KnownMove(m)&&m.name!="날개쉬기"?"상태 기술":"수동 판정")));}}Save();try{var result=Engine.Resolve(db,Fighters,commands,Rules,trainerStates,random.NextDouble,ChooseSwitch);ApplySwitchRecords(result);for(int i=0;i<2;i++)for(int k=0;k<reserves[i].Count;k++){var state=result.Rules.Parties[i].FirstOrDefault(x=>Mechanics.SameMember(x,reserves[i][k]));if(state!=null&&!state.OnField)reserves[i][k]=state.Copy();}log="TURN "+turn+"\r\n"+string.Join("\r\n",rangeLines)+"\r\n\r\n"+string.Join("\r\n",result.Log)+"\r\n\r\n────────────────────\r\n\r\n"+log;Fighters=result.Fighters;Rules=result.Rules;trainerStates=result.Trainers;selections=new[]{new TurnSelection(),new TurnSelection()};turn++;UpdateHere();RefreshView();ShowResults();}catch(Exception ex){undo.Pop();if(TestMode)throw;GameDialog.Show(this,ex.Message,"지시 확인",MessageBoxButtons.OK,MessageBoxIcon.Information);}}
  Fighter ChooseSwitch(SwitchRequest request){using(var dialog=new SwitchPromptForm(request))return dialog.ShowDialog(this)==DialogResult.OK?dialog.Selected:null;}
  void ApplySwitchRecords(TurnResult result){foreach(var change in result.Switches??new List<SwitchRecord>()){if(change==null||change.Incoming==null||change.Outgoing==null)continue;int incomingIndex=reserves[change.Side].FindIndex(x=>Mechanics.SameMember(x,change.Incoming));if(incomingIndex>=0)reserves[change.Side].RemoveAt(incomingIndex);var outgoing=change.Outgoing.Copy();Bench(outgoing);if(!reserves[change.Side].Any(x=>Mechanics.SameMember(x,outgoing)))reserves[change.Side].Add(outgoing);}}
   public void RefreshView(){var encoreLog=new List<string>();foreach(var fighter in Fighters){Mechanics.RefreshRollout(db,fighter,encoreLog);Mechanics.RefreshEncore(db,fighter,encoreLog);}if(encoreLog.Count>0)log=string.Join("\r\n",encoreLog)+"\r\n"+log;Mechanics.SetParties(Rules,Fighters,new IEnumerable<Fighter>[]{reserves[0],reserves[1]});UpdateHere();for(int i=0;i<2;i++){cards[i].ShowFighter(Fighters[i],Engine.Stats(Fighters[i],Fighters[1-i].Data.level,Rules)[0],i);moveCards[i].RefreshMoves(Fighters[i],db);directiveButtons[i].Text=DirectiveRules.Label(selections[i]);directiveButtons[i].Subtext=(trainers[i]==null?"트레이너 미적용":(trainers[i].name.Length>0?trainers[i].name:"이름 없는 트레이너"))+" · 대기 "+reserves[i].Count;directiveButtons[i].Enabled=Fighters[i].HP<=0||!Mechanics.AutoAction(Fighters[i]);if(!directiveButtons[i].Enabled)directiveButtons[i].Subtext="「"+Mechanics.AutoActionLabel(Fighters[i])+"」: 지정 불가";var extensionMoves=ExtensionMoves(i);extensionButtons[i].Enabled=extensionMoves.Length>0||selections[i].ExtensionMove.Length>0;extensionButtons[i].Subtext=selections[i].ExtensionMove.Length>0?"선택: "+selections[i].ExtensionMove:extensionMoves.Length>0?extensionMoves.Length+"개 가능":"없음";analyzeButtons[i].Enabled=!BattleRecords.IsAnalyzed(trainerStates[i],Fighters[1-i]);analyzeButtons[i].Subtext=analyzeButtons[i].Enabled?"도감 사용":"해석 완료";cards[i].StateLine.Text=RuleBook.Summary(Fighters[i],Fighters[1-i],Rules);hints.SetToolTip(cards[i].StateLine,cards[i].StateLine.Text);hints.SetToolTip(directiveButtons[i],trainers[i]==null?"팀 편집에서 트레이너를 적용하면 4식·지령을 선택할 수 있습니다.":"4식과 지령은 선택 사항이며 각 항목은 1시합 1회입니다.");for(int j=0;j<Fighters[i].Moves.Length;j++){var m=db.moves.FirstOrDefault(v=>v.name==Fighters[i].Moves[j]);if(m==null)continue;string block=Mechanics.TargetsOpponent(m)?Mechanics.Block(db,Fighters[i],Fighters[1-i],m,Rules):"";var button=moveCards[i].Buttons[j];string unavailable=Mechanics.MoveBlock(Fighters[i],m);button.Enabled=unavailable.Length==0;button.Subtext=unavailable.Length>0?MoveCard.RestrictionLabel(unavailable):string.Join("/",m.types)+" / "+(block.Length>0?"무효":m.category=="변화"?(Mechanics.KnownMove(m)&&m.name!="날개쉬기"?"상태 적용":"수동 판정"):"상성 ×"+Mechanics.TypeEffect(db,Fighters[i],Fighters[1-i],m,Rules));hints.SetToolTip(button,(block.Length>0?block+"\n":"")+m.effect+"\n등록된 효과 외에는 수동 판정입니다.");button.Invalidate();}}fieldLabel.Text=RuleBook.Field(Rules,Fighters);fieldEffectBadge.Summary=FieldEffectRuntime.Summary(Rules.FieldEffects);hints.SetToolTip(fieldEffectBadge,FieldEffectRuntime.Detail(Rules.FieldEffects));turnLabel.Text="TURN  "+turn.ToString("00");calculate.Enabled=Fighters.All(f=>f.HP>0);back.Enabled=undo.Count>0;status.Text=Fighters.Any(f=>f.HP<=0)?"포켓몬이 쓰러졌습니다. 교대하거나 초기화하세요.":"기술을 선택하고 필요하면 4식·지령·선행입력을 선언한 뒤 배틀 !";battleState.SetReport(BattleStateReport.Build(db,Fighters,Rules,selections,trainers,trainerStates,reserves));if(resultForm!=null&&!resultForm.IsDisposed)resultForm.SetLog(log);}
  void UpdateHere(){for(int side=0;side<2;side++){int living=(Fighters[side].HP>0?1:0)+reserves[side].Count(x=>x.HP>0);BattleRecords.UpdateHere(trainerStates[side],initialTeamSizes[side],living,Fighters[1-side],side,x=>log=x+"\r\n"+log);}}
  // 기능확장: 기술 목록에 없는 기술을 포텐셜이 허용한 범위에서 고른다
  string[] ExtensionMoves(int side){return FunctionExtensions.Available(Fighters[side],Fighters[1-side],Rules,trainers[side],reserves[side]).Where(x=>db.moves.Any(m=>m.name==x)).ToArray();}
  void PickExtension(int side){var moves=ExtensionMoves(side);var options=moves.Concat(selections[side].ExtensionMove.Length>0?new[]{"선택 해제"}:new string[0]).ToArray();if(options.Length==0){GameDialog.Show(this,"기능확장으로 내보낼 수 있는 기술이 없습니다.");return;}using(var dialog=new ChoiceDialog("기능확장",Fighters[side].Data.name+"이 기술 목록 밖에서 내보낼 기술",options)){if(dialog.ShowDialog(this)!=DialogResult.OK)return;string picked=options[dialog.Selected];selections[side].ExtensionMove=picked=="선택 해제"?"":picked;if(picked!="선택 해제")selections[side].SwitchIndex=-1;}RefreshView();}
  void Analyze(int side){var target=Fighters[1-side];if(BattleRecords.IsAnalyzed(trainerStates[side],target))return;Save();var eventLog=new List<string>();BattleRecords.RecordAnalysis(trainerStates[side],Fighters[side],reserves[side].Concat(new[]{Fighters[side]}),target,eventLog.Add);log=(side+1)+"팀이 도감으로 "+target.Data.name+"의 데이터를 해석했다.\r\n"+string.Join("\r\n",eventLog)+"\r\n\r\n"+log;using(var form=new AnalysisForm(target))form.ShowDialog(this);RefreshView();}
  // 「임의의 능력」·등급 범위 종족치는 사용자가 고른다(자동 검사·캡처에서는 고르지 않고 판정 대기·최솟값)
  string ChooseStat(PotentialInstance source,Fighter target,string[] options){if(TestMode||Theme.Instant||options==null||options.Length==0)return null;using(var dialog=new ChoiceDialog(source.Label+" · 임의의 능력",target.Data.name+"의 어느 능력을 바꿀까요?",options))return dialog.ShowDialog(this)==DialogResult.OK?options[dialog.Selected]:null;}
  int ChooseSpeciesValue(PotentialInstance source,Fighter target,int stat,int min,int max){if(TestMode||Theme.Instant||max<min)return -1;var values=Enumerable.Range(min,max-min+1).Select(x=>x.ToString()).ToArray();using(var dialog=new ChoiceDialog(source.Label+" · 종족치",target.Data.name+"의 "+Engine.Names[stat]+" 종족치를 정하세요 ("+min+"~"+max+")",values))return dialog.ShowDialog(this)==DialogResult.OK?min+dialog.Selected:-1;}
  string ChooseSealMove(Fighter target,string[] moves){if(TestMode||Theme.Instant||moves==null||moves.Length<2)return null;using(var dialog=new ChoiceDialog("봉인",target.Data.name+"의 기술 중 봉인할 기술을 고르세요",moves))return dialog.ShowDialog(this)==DialogResult.OK?moves[dialog.Selected]:null;}
  Move ChooseExtraMove(Fighter actor,Move[] candidates){if(TestMode||Theme.Instant||candidates==null||candidates.Length<2)return null;using(var dialog=new ChoiceDialog("추가행동",actor.Data.name+"의 추가행동 기술을 고르세요",candidates.Select(x=>x.name).ToArray()))return dialog.ShowDialog(this)==DialogResult.OK?candidates[dialog.Selected]:null;}
  bool ConfirmOptionalEffect(Fighter source,Fighter target,Potential potential){if(source==null||target==null||potential==null)return false;int side=Array.FindIndex(Fighters,x=>x!=null&&x.Data!=null&&Mechanics.SameMember(x,source));if(side<0||BattleRecords.IsAnalyzed(trainerStates[side],target))return false;if(GameDialog.Show(this,"『"+potential.name+"』으로 "+target.Data.name+"의 데이터를 해석할까요?","선택 발동",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return false;if(!PotentialQueue.Active)trainerStates[side].Analyzed.Add(BattleRecords.Key(target));using(var form=new AnalysisForm(target))form.ShowDialog(this);return true;}
  void ShowResults(){if(resultForm==null||resultForm.IsDisposed)resultForm=new ResultForm();resultForm.SetLog(log);if(!resultForm.Visible)resultForm.Show(this);resultForm.Activate();}
  void ShowTeamEditor(){if(dataEditorForm==null||dataEditorForm.IsDisposed){dataEditorForm=new DataEditorForm(LoadFromEditor,LoadTrainerFromEditor);dataEditorForm.FormClosed+=(s,e)=>dataEditorForm=null;dataEditorForm.Show(this);}else dataEditorForm.Activate();}
  void LoadFromEditor(PokemonRecord source,int side){string warning;var data=EditorBridge.ToPokemon(source,db,out warning,trainers[side],trainerStates[side]);Save();var fighter=new Fighter(data);fighter.AA=source.asciiArt;TrainerAccessRules.ApplyTrainerPassives(fighter,trainers[side],trainerStates[side]);if(!Mechanics.SameMember(Fighters[side].Data,data)){reserves[side].RemoveAll(x=>Mechanics.SameMember(x.Data,data));reserves[side].Add(Fighters[side].Copy());}Fighters[side]=fighter;selections[side]=new TurnSelection();log="팀 편집기에서 "+data.name+"을 "+(side==0?"왼쪽":"오른쪽")+" 배틀 슬롯에 불러왔습니다."+(warning.Length>0?"\r\n"+warning:"")+"\r\n\r\n"+log;RefreshView();status.Text=data.name+" → "+(side==0?"왼쪽":"오른쪽")+" 슬롯 적용 완료 · 이전 포켓몬은 대기"+(warning.Length>0?" (일부 항목 제외)":"");}
  void LoadTrainerFromEditor(TrainerRecord source,int side){Save();string json=new JavaScriptSerializer().Serialize(source);trainers[side]=new JavaScriptSerializer().Deserialize<TrainerRecord>(json);trainerStates[side]=new TrainerBattleState{Trainer=trainers[side]};selections[side]=new TurnSelection();log=(source.name.Length>0?source.name:"이름 없는 트레이너")+"를 TRAINER "+(side+1)+"에 적용했습니다. 지령 사용 이력이 초기화됩니다.\r\n\r\n"+log;RefreshView();}
  public void Smoke(){var old=Fighters[0].HP;var savedRules=Rules.Copy();Rules.Weather="비";Rules.WeatherTurns=3;Rules.Sides[0].Reflect=3;Battle();if(turn!=2||log.Length==0)throw new Exception("Turn UI failed");Undo();if(turn!=1||Fighters[0].HP!=old||Rules.WeatherTurns!=3||Rules.Sides[0].Reflect!=3)throw new Exception("Undo UI failed");Rules=savedRules;Rules.Sides[0].Reflect=0;Rules.Sides[0].StealthRock=true;Rules.Sides[1].Spikes=2;Rules.Sides[1].ToxicSpikes=1;RefreshView();if(resultForm!=null)resultForm.Close();using(var f=new FighterForm(db,Fighters[0],Fighters[1].Data.level,Rules)){f.CreateControl();}using(var f=new RulesForm(Rules)){f.CreateControl();}}
 }
 static class Program {
  static void Capture(Form form,string path){Application.DoEvents();using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
   [STAThread]public static int Main(string[] args){try{var db=Database.Load();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Fonts.Load();Theme.Instant=args.Length>0;if(args.Length>1&&args[0]=="--flow-preview"){FlowPreview.Run(db,args[1]);return 0;}if(args.Length==0){Application.Run(new StartForm(db));return 0;}var form=new MainForm(db);if(args.Length>1&&args[0]=="--render-preview"){form.TestMode=true;form.Shown+=(s,e)=>{form.Smoke();Capture(form,args[1]);var savedFighters=form.Fighters.Select(f=>f.Copy()).ToArray();var savedRules=form.Rules.Copy();form.Rules.Weather="비";form.Rules.WeatherTurns=3;form.Rules.Terrain="일렉트릭필드";form.Rules.TerrainTurns=4;form.Fighters[0].Status="마비";form.Rules.Sides[1].Reflect=3;form.RefreshView();Capture(form,args[1]+".active.png");form.Fighters=savedFighters;form.Rules=savedRules;form.RefreshView();using(var conditions=new ConditionsForm(db,form.Fighters[0],form.Fighters[1],form.Rules)){conditions.Show();Capture(conditions,args[1]+".conditions.png");conditions.Close();}using(var guide=new GuideForm(db)){guide.Show();Capture(guide,args[1]+".guide.png");guide.Close();}using(var editor=new FighterForm(db,form.Fighters[0],form.Fighters[1].Data.level,form.Rules)){editor.Show();Capture(editor,args[1]+".editor.png");editor.Close();}using(var settings=new RulesForm(form.Rules)){settings.Show();Capture(settings,args[1]+".settings.png");settings.Close();}using(var result=new ResultForm()){result.SetLog("TURN 01\r\n선데이의 파괴광선!\r\n잭 한마에게 297 대미지.");result.Show();Capture(result,args[1]+".log.png");result.Close();}form.Close();};}Application.Run(form);return 0;}catch(Exception ex){if(args.Length>0){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"error.txt"),ex.ToString());return 1;}GameDialog.Show(ex.Message,"AA BATTLE 오류",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
 }
